mirror.source:
import fs from 'node:fs';
import path from 'node:path';
import crypto from 'node:crypto';
const base='https://minor-incident.com', out=path.resolve('test-results/perf6/prod');
const queue=['/'], seen=new Set(), rows=[], failures=[];
function add(s, parent='/') { try { const u=new URL(s,base+parent); if(u.origin!==base || u.pathname.includes('..'))return; const p=u.pathname; if(!seen.has(p)&&!queue.includes(p))queue.push(p); }catch{} }
function refs(body,parent){ for(const m of body.matchAll(/(?:["'`])((?:\.?\.?\/|\/)?[^\s"'`<>\\]*?\.(?:js|css|wasm|json|glb|png|webp|ktx2|gz|webm|m4a|svg|ico|webmanifest))(?:\?[^"'`\s]*)?["'`]/g)){ let s=m[1]; if(s.startsWith('assets/')||s.startsWith('build/'))s='/'+s; if(s.startsWith('/')||s.startsWith('./')||s.startsWith('../'))add(s,parent); } }
for(const p of fs.readdirSync('public',{recursive:true}).map(String)) if(fs.statSync(path.join('public',p)).isFile()&&!p.startsWith('_')&&!p.includes('motionlab')&&p!=='perf-device.html')add('/'+p);
async function worker(){while(queue.length){const p=queue.shift();if(seen.has(p))continue;seen.add(p);try{let r;for(let t=0;t<3;t++){try{r=await fetch(base+p,{signal:AbortSignal.timeout(45000)});if(!r.ok)throw Error('HTTP '+r.status);break}catch(e){if(t===2)throw e;}}const data=Buffer.from(await r.arrayBuffer()),type=r.headers.get('content-type');if(type?.includes('text/html')&&p!=='/'&&!p.endsWith('.html')){failures.push({path:p,error:'SPA fallback (not a deployed file)'});continue;}const file=path.join(out,p==='/'?'index.html':p);fs.mkdirSync(path.dirname(file),{recursive:true});fs.writeFileSync(file,data);rows.push({path:p,bytes:data.length,sha256:crypto.createHash('sha256').update(data).digest('hex'),contentType:type});if(/\.(?:js|css|json|webmanifest)$/.test(p)||p==='/')refs(data.toString(),p);if(rows.length%250===0)console.log(JSON.stringify({downloaded:rows.length,pending:queue.length,failures:failures.length}));}catch(e){failures.push({path:p,error:String(e)});}}}
await Promise.all(Array.from({length:12},worker));
const index=fs.readFileSync(path.join(out,'index.html'),'utf8');if(!index.includes('index-DSZ-4VAt.js'))throw Error('wrong baseline bundle');
fs.writeFileSync('test-results/perf6/mirror.json',JSON.stringify({origin:base,at:new Date().toISOString(),expectedBundle:'index-DSZ-4VAt.js',verified:true,rows:rows.sort((a,b)=>a.path.localeCompare(b.path)),failures},null,2));console.log(JSON.stringify({complete:true,downloaded:rows.length,bytes:rows.reduce((n,r)=>n+r.bytes,0),failures:failures.length}));

adapterEntry.source:
import { installTestApi } from '../../src/debug/testApi';
export async function install(game: Parameters<typeof installTestApi>[0], ready: Promise<void>) {
  const settled = ready.then(async () => {
    await (game as unknown as { audioLoad: Promise<void> }).audioLoad;
    if ((game as unknown as { speculativeRunning: boolean }).speculativeRunning) await game.loadLevel('L1', { seed: Number(game.params.get('seed') ?? 1) });
  });
  installTestApi(game, settled);
  (window as unknown as { __SCENE__: { game: typeof game } }).__SCENE__ = { game };
}

