import fs from 'node:fs';
import {spawn} from 'node:child_process';
const status={started:new Date().toISOString(),jobs:[]};
const prior=JSON.parse(fs.readFileSync("test-results/perf6/run-status.json","utf8"));fs.writeFileSync("test-results/perf6/rejected-run-status.json",JSON.stringify(prior,null,2));
for(const tier of ['low','high'])for(const selection of ['L1,L2','L3,L4','L5,L6','L7,L8','L9,L10']){
 const env={...process.env,RELEASE_QUALITY:tier,RELEASE_SECONDS:'60',RELEASE_PERF_ONLY:'1',RELEASE_OUT:`test-results/perf6/matrix/${tier}`,PERF_CONDITIONS_LOG:'test-results/perf6/quiet.jsonl'};
 const loadPath=`test-results/perf6/matrix/${tier}/loads/${selection.replaceAll(',', '-')}.json`;
 const hasLoads=fs.existsSync(loadPath)&&JSON.parse(fs.readFileSync(loadPath,'utf8')).length===8;
 const args=['tools/perf/quiet-run.sh','sh','-c',`${hasLoads?"":`node --import tsx tools/qa/release-ab-load.mjs ${selection} && `}node --import tsx tools/qa/release-ab-browser.mjs strips ${selection} webgpu`];
 const row={tier,selection,started:new Date().toISOString(),command:['sh',...args]};status.jobs.push(row);fs.writeFileSync('test-results/perf6/run-status.json',JSON.stringify(status,null,2));console.log('START',tier,selection);
 row.exitCode=await new Promise(resolve=>{const child=spawn('sh',args,{env,stdio:'inherit'});child.on('exit',(c,s)=>resolve(c??s));});row.finished=new Date().toISOString();fs.writeFileSync('test-results/perf6/run-status.json',JSON.stringify(status,null,2));console.log('DONE',tier,selection,row.exitCode);
 if(row.exitCode!==0){console.log('STOP on failed job for inspection');process.exit(1);}
}

reportGenerator.source:
import json,math,hashlib,platform
from pathlib import Path
ROOT=Path('test-results/perf6')
OUT=Path('docs/reports/perf6');OUT.mkdir(exist_ok=True,parents=True)
def read(p):return json.loads(Path(p).read_text())
def stats(frames):
 s=sorted(frames)
 return dict(frames=len(s),p95Ms=s[math.ceil(len(s)*.95)-1] if s else None,maxMs=s[-1] if s else None)
def frame_pass(p,c):
 issues=[]
 if c['p95Ms']>p['p95Ms']+1+1e-6:issues.append('p95 > PROD+1 ms')
 if round(c['maxMs']/(1000/60))>round(p['maxMs']/(1000/60))+1:issues.append('max > PROD+1 frame')
 if c['maxMs']>=66 and p['maxMs']<66:issues.append('new >=66 ms spike')
 return issues
rows=[];traces=[];loads=[];moments=[];moment_sources=[]
for tier in ['low','high']:
 for p in sorted((ROOT/'matrix'/tier/'loads').glob('L*.json')):
  for r in read(p):loads.append({k:r.get(k) for k in ['side','level','tier','backend','diagnostic','temperature','measuredAt','errors','ms','contexts','adapter','glRenderer','quality','bundle','begin','stages','loadMeasures']})
 for p in sorted((ROOT/'matrix'/tier/'strips/webgpu').glob('L*.json')):
  for r in read(p):
   f=r.get('performance',{});fs=f.get('frames',[])
   traces.append(dict(side=r['side'],level=r['level'],tier=tier,hardware=r.get('hardware'),measuredAt=r['measuredAt'],proof=r.get('proof'),nativeBeat=r.get('nativeBeat'),control=r.get('control'),terminalInputWithheld=r.get('terminalInputWithheld'),diagnostic=r.get('diagnostic'),failure=r.get('failure'),errors=r['errors'],samples=[{k:v for k,v in sample.items() if k in ['wallSeconds','scenario','loading','tick','backend','quality','player','alive','alphas','objective','phase','completed']} for sample in r['samples']],performance={k:f.get(k) for k in ['startedAt','tick','level','durationMs','endTick','nonGameplayFrames','frames','chargeFrames','builds','maxMs','p95Ms']},events=[{k:e[k] for k in ['type','tick','sourceId','targetId','actionId','attackId','weapon','id'] if k in e} for e in f.get('events',[])]))
 for p in sorted((ROOT/'webgl2'/tier/'loads').glob('L*.json')):
  for r in read(p):loads.append({k:r.get(k) for k in ['side','level','tier','backend','diagnostic','temperature','measuredAt','errors','ms','contexts','adapter','glRenderer','quality','bundle','begin','stages','loadMeasures']})
for n in range(1,11):
 for tier in ['low','high']:
  level=f'L{n}';samples={r['side']:r for r in traces if r['level']==level and r['tier']==tier};sides={};issues=[]
  for side in ['prod','candidate']:
   r=samples.get(side);ls={r['temperature']:r for r in loads if r['level']==level and r['tier']==tier and r['backend']=='webgpu' and r['side']==side}
   if not r or len(ls)!=2:issues.append(f'{side}: incomplete');continue
   f=r['performance'];sides[side]=dict(p95Ms=f['p95Ms'],maxMs=f['maxMs'],durationMs=f['durationMs'],frames=len(f.get('frames',[])),lateMaterialBuilds=len([b for b in f.get('builds',[]) if not b['loading']]),loads={t:ls[t]['ms']/1000 for t in ['cold','warm']})
   if r['failure'] or r['errors'] or r['diagnostic'] or f['nonGameplayFrames'] or f['durationMs']<60000:issues.append(f'{side}: invalid window')
   if any(s['backend']!='webgpu' or s['quality']!=tier or s['scenario']!=level for s in r['samples']):issues.append(f'{side}: wrong backend/tier/level')
   if any(x['errors'] or 'webgpu' not in x['contexts'] for x in ls.values()):issues.append(f'{side}: invalid loads')
  if len(sides)==2:
   p,c=sides['prod'],sides['candidate'];issues+=frame_pass(p,c)
   for t in ['cold','warm']:
    if c['loads'][t]>6 or c['loads'][t]>p['loads'][t]+.5:issues.append(t+' load')
  rows.append(dict(scope='WebGPU',cell=level+' '+tier,level=level,tier=tier,sides=sides,issues=issues,verdict='NOT RUN' if len(sides)!=2 else 'FAIL' if issues else 'PASS'))
for n in [4,5,6,10]:
 for tier in ['low','high']:
  level=f'L{n}';sides={};issues=[]
  for side in ['prod','candidate']:
   ls={r['temperature']:r for r in loads if r['level']==level and r['tier']==tier and r['backend']=='webgl2' and r['side']==side}
   if len(ls)!=2:issues.append(side+': incomplete');continue
   sides[side]=dict(loads={t:ls[t]['ms']/1000 for t in ['cold','warm']})
   if any(x['errors'] or 'webgl2' not in x['contexts'] or 'webgpu' in x['contexts'] for x in ls.values()):issues.append(side+': invalid load')
  if len(sides)==2:
   for t in ['cold','warm']:
    if sides['candidate']['loads'][t]>6 or sides['candidate']['loads'][t]>sides['prod']['loads'][t]+.5:issues.append(t+' load')
  rows.append(dict(scope='WebGL2 load',cell=level+' '+tier,level=level,tier=tier,sides=sides,issues=issues,verdict='NOT RUN' if len(sides)!=2 else 'FAIL' if issues else 'PASS'))
for p in (ROOT/'moments').glob('*.json'):
 for r in read(p):
  moment_sources.append(r)
  windows={}
  if r['level']=='L1':
   shutters=[f for f in r['frames'] if f['shutter']]
   if shutters:
    start=shutters[0]['at'];windows['L1 shutter closure (-0.5/+2 s)']=[f['ms'] for f in r['frames'] if start-500<=f['at']<=start+2000]
   windows['L1 full accident-to-shutter route']=[f['ms'] for f in r['frames']]
  else:
   windows['L3 fresh handgun/armory, full 60 s']=[f['ms'] for f in r['frames']]
   windows['L3 old tick 1031 ±60 ticks']=[f['ms'] for f in r['frames'] if 971<=f['tick']<=1091]
  for name,values in windows.items():moments.append(dict(name=name,tier=r['tier'],side=r['side'],measuredAt=r['measuredAt'],errors=r['errors'],durationMs=r['durationMs'],**stats(values)))
for r in traces:
 if r['level']=='L10':
  f=r['performance'];c=f.get('chargeFrames') or []
  for second in [43,55]:
   values=[f['frames'][i] for i,v in enumerate(c) if v['charge']//60==second]
   if values:moments.append(dict(name=f'L10 charge {second}/60',tier=r['tier'],side=r['side'],errors=r['errors'],**stats(values)))
 if r['level']=='L3' and r['tier']=='high':moments.append(dict(name='L3 station-defense matrix route',tier='high',side=r['side'],errors=r['errors'],**stats(r['performance']['frames'])))
for name in ['L1 full accident-to-shutter route','L1 shutter closure (-0.5/+2 s)','L3 fresh handgun/armory, full 60 s','L3 old tick 1031 ±60 ticks','L10 charge 43/60','L10 charge 55/60','L3 station-defense matrix route']:
 for tier in (['high'] if 'station-defense' in name else ['low','high']):
  sides={r['side']:r for r in moments if r['name']==name and r['tier']==tier};issues=[]
  if len(sides)!=2:issues.append('incomplete')
  else:
   issues+=frame_pass(sides['prod'],sides['candidate'])
   if any(r['errors'] or not r['frames'] for r in sides.values()):issues.append('invalid window')
  rows.append(dict(scope='Moment',cell=name+' '+tier,tier=tier,sides=sides,issues=issues,verdict='NOT RUN' if len(sides)!=2 else 'FAIL' if issues else 'PASS'))
(OUT/'matrix.json').write_text(json.dumps(dict(rows=rows,loads=loads,moments=moments),indent=2)+'\n')
(OUT/'moments-sources.json').write_text(json.dumps(moment_sources,separators=(',',':'))+'\n')
(OUT/'frames.json').write_text(json.dumps(traces,separators=(',',':'))+'\n')
print(json.dumps(dict(complete=sum(r['verdict']!='NOT RUN' for r in rows),passCount=sum(r['verdict']=='PASS' for r in rows),failures=[{k:r[k] for k in ['scope','cell','issues']} for r in rows if r['verdict']=='FAIL']),indent=2))

diagnosticReportGenerator.source:
import fs from 'node:fs';import zlib from 'node:zlib';import crypto from 'node:crypto';
const hash=b=>crypto.createHash('sha256').update(b).digest('hex');
function cpu(file,row){const raw=fs.readFileSync(file),p=JSON.parse(zlib.gunzipSync(raw)),nodes=new Map(p.nodes.map(n=>[n.id,n])),sums=new Map();let idle=0,total=0;for(let i=0;i<p.samples.length;i++){const n=nodes.get(p.samples[i]),ms=(p.timeDeltas[i]??0)/1000,key=`${n.callFrame.functionName||'(anonymous)'} ${n.callFrame.url?.split('/').at(-1)||''}:${n.callFrame.lineNumber}`;sums.set(key,(sums.get(key)||0)+ms);total+=ms;if(n.callFrame.functionName==='(idle)')idle+=ms;}
 const phase=row.loadMeasures.find(m=>m.name==='view:civilian-crowd');let at=p.performanceStartedAt,phaseIdle=0,phaseTotal=0;if(phase)for(let i=0;i<p.samples.length;i++){const ms=(p.timeDeltas[i]??0)/1000,end=at+ms,dt=Math.max(0,Math.min(end,phase.startTime+phase.duration)-Math.max(at,phase.startTime));if(dt){phaseTotal+=dt;if(nodes.get(p.samples[i]).callFrame.functionName==='(idle)')phaseIdle+=dt;}at=end;}
 return {rawPath:file,rawSha256:hash(raw),rawBytes:raw.length,nodes:p.nodes.length,samples:p.samples.length,totalMs:total,idleMs:idle,civilianPhase:phase?{durationMs:phase.duration,mappedProfileMs:phaseTotal,idleMs:phaseIdle,clockAlignment:'performanceStartedAt captured just before Profiler.start; CDP start latency is not corrected'}:null,topSelfTime:[...sums].sort((a,b)=>b[1]-a[1]).slice(0,40).map(([label,selfMs])=>({label,selfMs}))};}
const all=[];
for(const [dataset,tier,level] of [['load-diagnostic','low','L5'],['load-diagnostic','low','L7'],['deep-diagnostic','low','L7'],['deep-diagnostic','high','L7'],['webgl2-diagnostic','low','L5']]){const rows=JSON.parse(fs.readFileSync(`test-results/perf6/${dataset}/${tier}/loads/${level}.json`));for(const r of rows){all.push({dataset,side:r.side,level:r.level,tier:r.tier,temperature:r.temperature,diagnostic:true,measuredAt:r.measuredAt,ms:r.ms,bundle:r.bundle,errors:r.errors,adapter:r.adapter,contexts:r.contexts,stages:r.stages,phases:r.loadMeasures.filter(m=>m.startTime>=r.start).map(m=>({name:m.name,at:m.startTime-r.start,ms:m.duration})),spans:r.diagnosticSpans,workerEvents:(r.diagnosticWorkerEvents??[]).map(e=>({...e,at:e.at-r.start,afterReady:e.at>r.done})),resources:r.resources.filter(e=>e.startTime>=r.start).map(e=>({path:new URL(e.name).pathname,type:e.initiatorType,at:e.startTime-r.start,end:e.responseEnd-r.start,bytes:e.encodedBodySize})),cpu:cpu(`test-results/perf6/${dataset}/${tier}/loads/${level}-${r.side}-${r.temperature}.cpuprofile.gz`,r)});}}
const analysis={acceptanceReplacement:false,notes:['All original acceptance load failures remain selected; these CPU-profiled observations are diagnostic only.','L5 original excess: HUD-end to card-close 886.3 ms candidate vs 441.1 ms PROD; subsequent graph count 272 on each, final diagnostic fence ~16 ms on each. A candidate-only source cause is unproven.','L7 original excess: civilian readiness 1708.0 ms candidate vs 655.1 ms PROD. The slow readiness path recurs on PROD in diagnostics. Original dependency is unresolved; CPU profile and worker completions do not establish a new candidate CPU-bake hotspot.'],samples:all};
fs.writeFileSync('docs/reports/perf6/diagnostics.json',JSON.stringify(analysis,null,2)+'\n');console.log(all.map(r=>({level:r.level,side:r.side,temp:r.temperature,ms:r.ms,idleMs:r.cpu.idleMs,civilianIdleMs:r.cpu.civilianPhase?.idleMs})));

