import fs from 'node:fs';import zlib from 'node:zlib';import crypto from 'node:crypto';
const hash=b=>crypto.createHash('sha256').update(b).digest('hex');
function profileWindows(file,row,peaks){
 const raw=fs.readFileSync(file),p=JSON.parse(zlib.gunzipSync(raw)),nodes=new Map(p.nodes.map(n=>[n.id,n])),parents=new Map();for(const n of p.nodes)for(const id of n.children??[])parents.set(id,n.id);
 const nativeOffset=(row.performance.startedAt-p.performanceStartedAt)*1000,segments=[];
 for(const peak of peaks){const lo=nativeOffset+(peak.at-peak.ms)*1000,hi=nativeOffset+peak.at*1000,selected=[],keep=new Set(),inclusive=new Map(),self=new Map();let clock=0;
  for(let i=0;i<p.samples.length;i++){const duration=p.timeDeltas[i]??0,end=clock+duration,from=Math.max(clock,lo),to=Math.min(end,hi);clock=end;if(to<=from)continue;const id=p.samples[i],dt=to-from;selected.push([id,from,dt]);const cf=nodes.get(id).callFrame,key=cf.functionName+' '+cf.url.split('/').at(-1)+':'+cf.lineNumber+':'+cf.columnNumber;self.set(key,(self.get(key)||0)+dt/1000);const seen=new Set();for(let n=id;n!==undefined;n=parents.get(n)){keep.add(n);const cf=nodes.get(n).callFrame,key=cf.functionName+' '+cf.url.split('/').at(-1)+':'+cf.lineNumber+':'+cf.columnNumber;if(!seen.has(key)){seen.add(key);inclusive.set(key,(inclusive.get(key)||0)+dt/1000);}}}
  const top=m=>[...m].sort((a,b)=>b[1]-a[1]).slice(0,30).map(([label,ms])=>({label,ms}));
  segments.push({frame:peak,profileRelativeFromUs:lo,profileRelativeToUs:hi,sampleSchema:['nodeId','profileRelativeStartUs','clippedDurationUs'],samples:selected,nodes:[...keep].map(id=>{const n=nodes.get(id);return {...n,children:(n.children??[]).filter(id=>keep.has(id))}}),selfTime:top(self),inclusiveTime:top(inclusive)});
 }
 return {rawPath:file,rawSha256:hash(raw),rawBytes:raw.length,profilePerformanceStartedAt:p.performanceStartedAt,nativeStartedAt:row.performance.startedAt,clockAlignment:'performanceStartedAt is recorded immediately before Profiler.start; CDP start latency is not corrected',segments};
}
const samples=[];
for(const dataset of ['l10-diagnostic','l10-comparative-diagnostic']){const file=`test-results/perf6/${dataset}/strips/webgpu/L10.json`;if(!fs.existsSync(file))continue;for(const r of JSON.parse(fs.readFileSync(file))){const f=r.performance;const peaks=f.frames.map((ms,i)=>({index:i,ms,...f.chargeFrames[i],cpu:f.cpuFrames[i]})).sort((a,b)=>b.ms-a.ms).slice(0,3),nav=f.navCalls??[],bakes=f.frozenBakes??[];samples.push({dataset,side:r.side,tier:r.tier,measuredAt:r.measuredAt,diagnostic:true,acceptanceReplacement:false,errors:r.errors,failure:r.failure,durationMs:f.durationMs,p95Ms:f.p95Ms,maxMs:f.maxMs,finalSave:r.finalSave,nativePeakFrames:peaks,navigation:{calls:nav.length,totalMs:nav.reduce((n,c)=>n+c.ms,0),maxMs:Math.max(0,...nav.map(c=>c.ms)),slowest:[...nav].sort((a,b)=>b.ms-a.ms).slice(0,10)},frozenPoseBakes:{calls:bakes.length,maxMs:Math.max(0,...bakes.map(c=>c.ms)),slowest:[...bakes].sort((a,b)=>b.ms-a.ms).slice(0,10)},layoutCalls:[...(f.layoutCalls??[])].sort((a,b)=>b.ms-a.ms).slice(0,30),materialBuilds:f.builds,profile:profileWindows(`test-results/perf6/${dataset}/strips/webgpu/L10-${r.side}.cpuprofile.gz`,r,peaks)});}}
