import json,math,hashlib,subprocess
from pathlib import Path
P=Path('docs/reports/perf6')
def read(name):return json.loads((P/name).read_text())
def require(value,message):
 if not value:raise AssertionError(message)
m=read('matrix.json');rows=m['rows'];traces=read('frames.json');fresh=read('moments-sources.json');results={};boundary_samples=[]
require(len(rows)==41,'41 scoped cells/moments');require(len({(r['scope'],r['cell']) for r in rows})==41,'unique verdict rows')
require(all(r['verdict'] in ['PASS','FAIL'] for r in rows),'every row measured')
require(sum(r['scope']=='WebGPU' for r in rows)==20,'20 WebGPU cells');require(sum(r['scope']=='WebGL2 load' for r in rows)==8,'8 WebGL2 load cells');require(sum(r['scope']=='Moment' for r in rows)==13,'13 moment rows including two full L1 routes')
require(len(traces)==40,'40 paired full-minute traces');require(len(m['loads'])==112,'112 cold/warm menu measurements')
require(len(fresh)==8,'8 fresh L1/L3 source runs')
require(len({(r['level'],r['tier'],r['side']) for r in traces})==40,'unique native traces')
require(len({(r['level'],r['tier'],r['side'],r['backend'],r['temperature']) for r in m['loads']})==112,'unique load receipts')
require(len({(r['level'],r['tier'],r['side']) for r in fresh})==8,'unique fresh routes')
source_hashes=read('provenance.json')['sourceHashes']
for file,digest in source_hashes.items():require(hashlib.sha256(Path(file).read_bytes()).hexdigest()==digest,'unchanged source '+file)
for r in traces:
 f=r['performance'];samples=r['samples'];label=f"{r['level']} {r['tier']} {r['side']}"
 require(not r['errors'] and not r['failure'] and not r['diagnostic'],'valid trace '+label)
 require(f['durationMs']>=60000 and f['nonGameplayFrames']==0,'full native minute '+label)
 require(len(samples)>=10 and all(s['backend']=='webgpu' and s['quality']==r['tier'] and s['scenario']==r['level'] and not s['loading'] for s in samples),'sampled backend/tier/level '+label)
 require(r['hardware']['vendor']=='apple' and r['hardware'].get('isFallbackAdapter') is False,'native GPU '+label)
 frames=f['frames'];require(frames and all(math.isfinite(x) for x in frames) and frames[0]>=-1 and all(x>0 for x in frames[1:]),'finite frames/only sub-ms initial clock offset '+label)
 if frames[0]<=0:
  physical=sorted(frames[1:]);require(abs(physical[math.ceil(len(physical)*.95)-1]-f['p95Ms'])<1e-6 and max(physical)==f['maxMs'],'statistics unaffected by initial clock offset '+label);boundary_samples.append({'trace':label,'index':0,'ms':frames[0]})
 ordered=sorted(frames);require(abs(max(frames)-f['maxMs'])<1e-6 and abs(ordered[math.ceil(len(ordered)*.95)-1]-f['p95Ms'])<1e-6,'frame statistics '+label)
for r in m['loads']:
 label=f"{r['level']} {r['tier']} {r['side']} {r['backend']} {r['temperature']}"
 require(not r['diagnostic'] and not r['errors'] and r['quality']==r['tier'],'valid load '+label)
 require(r['temperature'] in ['cold','warm'] and r['ms']>0,'load temperature/time '+label)
 expected='index-DSZ-4VAt.js' if r['side']=='prod' else 'index-CsuHqSQb.js'
 require(r['bundle'].endswith(expected),'source bundle '+label)
 if r['backend']=='webgpu':require('webgpu' in r['contexts'] and 'webgl2' not in r['contexts'] and r['adapter']['vendor']=='apple' and r['adapter']['fallback'] is False,'WebGPU load hardware '+label)
 else:require('webgl2' in r['contexts'] and 'webgpu' not in r['contexts'] and 'Metal' in r['glRenderer'] and 'SwiftShader' not in r['glRenderer'],'WebGL2 Metal hardware '+label)
for r in fresh:
 label=f"{r['level']} {r['tier']} {r['side']}"
 require(not r['diagnostic'] and not r['errors'] and r['backend']=='webgpu' and r['quality']==r['tier'],'valid fresh moment '+label)
 require(r['startTick']==0,'fresh tick zero '+label)
 frames=[f['ms'] for f in r['frames']]
 require(all(math.isfinite(x) for x in frames) and frames[0]>=-5 and all(x>0 for x in frames[1:]),'fresh frames/initial clock origin '+label)
 if frames[0]<=0:
  physical=sorted(frames[1:]);require(abs(physical[math.ceil(len(physical)*.95)-1]-r['p95Ms'])<1e-6 and max(physical)==r['maxMs'],'fresh statistics unaffected by initial clock offset '+label);boundary_samples.append({'trace':'fresh '+label,'index':0,'ms':frames[0]})
 if r['level']=='L1':
  closed=[f for f in r['frames'] if f['shutter']];require(closed and any(not f['shutter'] for f in r['frames']),'shutter transition inside run '+label)
  require(r['frames'][-1]['at']-closed[0]['at']>=1999,'two seconds after closure '+label)
 else:
  require(r['durationMs']>=59980 and r['state']['phase']=='playing' and r['state'].get('l3'),'60-second wall-clock loop/last RAF within one frame '+label)
  attacks=[e for e in r['events'] if e['type']=='combat.attack' and e.get('actionId')=='weapon.handgun'];require(attacks,'first native handgun shot '+label)
  require(any(e['type']=='objective.completed' and (e.get('id')=='armory' or e.get('objectiveId')=='armory' or e.get('objective')=='armory') for e in r['events']),'fresh armory completion '+label)
def check_stats(values,record,label):
 require(values,'nonempty exact window '+label)
 ordered=sorted(values)
 require(record['frames']==len(values) and abs(record['maxMs']-max(values))<1e-6 and abs(record['p95Ms']-ordered[math.ceil(len(values)*.95)-1])<1e-6,'exact source window statistics '+label)
for r in rows:
 for side,record in r['sides'].items():
  label=r['cell']+' '+side
  if r['scope']!='Moment':
   backend='webgpu' if r['scope']=='WebGPU' else 'webgl2'
   for temperature in ['cold','warm']:
    receipt=next(x for x in m['loads'] if (x['level'],x['tier'],x['side'],x['backend'],x['temperature'])==(r['level'],r['tier'],side,backend,temperature))
    require(abs(record['loads'][temperature]-receipt['ms']/1000)<1e-9,'exact menu receipt '+label+' '+temperature)
   if backend=='webgpu':
    trace=next(x for x in traces if (x['level'],x['tier'],x['side'])==(r['level'],r['tier'],side))
    check_stats(trace['performance']['frames'],record,label)
  else:
   name=record['name']
   if name.startswith(('L1 ','L3 fresh','L3 old')):
    source=next(x for x in fresh if (x['level'],x['tier'],x['side'])==(name[:2],r['tier'],side));fs=source['frames']
    if name.startswith('L1 shutter'):
     at=next(f['at'] for f in fs if f['shutter']);values=[f['ms'] for f in fs if at-500<=f['at']<=at+2000]
    elif name.startswith('L3 old'):values=[f['ms'] for f in fs if 971<=f['tick']<=1091]
    else:values=[f['ms'] for f in fs]
   else:
    trace=next(x for x in traces if (x['level'],x['tier'],x['side'])==(name[:3] if name.startswith('L10') else 'L3',r['tier'],side));f=trace['performance']
    if name.startswith('L10'):
     second=int(name.split()[2].split('/')[0]);require(len(f['frames'])==len(f['chargeFrames']),'charge/frame alignment '+label)
     values=[ms for ms,c in zip(f['frames'],f['chargeFrames']) if second*60<=c['charge']<(second+1)*60]
    else:values=f['frames']
   check_stats(values,record,label)
 p,c=(r['sides'][s] for s in ['prod','candidate']);issues=[]
 if r['scope']!='WebGL2 load':
  if c['p95Ms']>p['p95Ms']+1+1e-6:issues.append('p95 > PROD+1 ms')
  if round(c['maxMs']/(1000/60))>round(p['maxMs']/(1000/60))+1:issues.append('max > PROD+1 frame')
  if c['maxMs']>=66 and p['maxMs']<66:issues.append('new >=66 ms spike')
 if r['scope']!='Moment':
  for t in ['cold','warm']:
   if c['loads'][t]>6 or c['loads'][t]>p['loads'][t]+.5:issues.append(t+' load')
 require(set(issues)==set(r['issues']),'independent verdict '+r['cell'])
 require(r['verdict']==('FAIL' if issues else 'PASS'),'verdict label '+r['cell'])
results.update(result='PASS: complete coverage and independently recomputed verdicts (performance failures remain)',rows=len(rows),webgpuCells=20,webgl2LoadCells=8,moments=13,nativeTraces=len(traces),loadMeasurements=len(m['loads']),freshMomentRuns=len(fresh),nativeMinDurationMs=min(r['performance']['durationMs'] for r in traces),sourceUnchanged=True,initialClockOffsetSamples=boundary_samples,failedRows=[{'scope':r['scope'],'cell':r['cell'],'issues':r['issues']} for r in rows if r['verdict']=='FAIL'])
(P/'audit.json').write_text(json.dumps(results,indent=2)+'\n');print(json.dumps(results,indent=2))

